'use strict';
const fs=require('node:fs'),path=require('node:path'),zlib=require('node:zlib'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const repo=path.resolve(__dirname,'..'),D=path.join(repo,'reports/ai-foundation-20261119'),read=p=>JSON.parse(fs.readFileSync(p)),rt=read(path.join(D,'v486-random20-runtime-preflight-20261119-v1.json')).runtime,seat='player-white';
const prep=read(path.join(D,'teacher-r4-order-preparation-20261119-v1.json')),cold=read(path.join(D,'teacher-r4-order-analysis-first-cold-20261119-v1.json'));assert(cold.cold.gatePassed);
