const record=read(path.join(repo,'reports/research/adcb348b.42c7f5fd.full.terminal-recovery.json')),save=read(path.join(repo,record.savePath));
const ns=new Map(cold.search.lines.map(n=>[n.node,n]));let node=ns.get(0),seen=new Set([0]),challengerSteps=[];
while(node.edges.length){const choices=node.edges.filter(e=>ns.has(e.target)&&ns.get(e.target).value===node.value&&!seen.has(e.target));assert(choices.length);const edge=choices.sort((a,b)=>(ns.get(a.target).distance??999)-(ns.get(b.target).distance??999)||a.actionId.localeCompare(b.actionId))[0];challengerSteps.push(...edge.steps);node=ns.get(edge.target);seen.add(node.node);}
assert.equal(node.status,'turn-boundary');assert.equal(node.value,237.5);
const {createSeededRandom}=require(path.join(rt,'randomizer/game/random')),{createSimulationRuleComposition}=require(path.join(rt,'randomizer/training/simulation-rule-composition')),{buildRuleObservation}=require(path.join(rt,'randomizer/app/rule-observation')),{createAnalysisPort}=require(path.join(rt,'randomizer/game/ai/analysis-port')),value=require(path.join(rt,'randomizer/game/ai/state-value'));
