const {composition:c}=createSimulationRuleComposition({seed,activePlayerCount:4,random,rngState,trustedProjectionReader:true,projectCounterfactualState:(s,v)=>buildRuleObservation(s,seed,v?.playerId)});
const output=path.join(D,'teacher-r4-two-action-order-control-20261119-v1.json');assert(!fs.existsSync(output));
const report={schemaVersion:'seti-teacher-r4-native-two-action-order-control-v1',status:'running',nativeInputs:0,newAISearches:0,newGames:0,branches:{},commonBoundary:'After two White main actions and all selected end-turn effects, before next White main. Landing-first+analysis versus analysis-first+same-Neptune-landing (both include the held fossil transport).'};
