function submit(id){const x=c.inspect(),d=x.phase==='awaiting_input'?x.session.decision:null,menu=d?d.choices:c.inputPort.enumerateActions({}),a=menu.find(a=>a.actionId===id);assert(a,'Missing Native action '+id);assert.equal(a.actorId,seat);const r=d?c.inputPort.submitDecision({decisionId:d.decisionId,decisionVersion:d.decisionVersion,ownerId:d.ownerId,choice:a}):a.phase==='quick'?c.inputPort.submitQuickAction(a):c.inputPort.submitAction(a);assert(r.ok,JSON.stringify(r));report.nativeInputs++;persist();return a;}
function facts(e){const s=JSON.parse(e.committedState),p=s.players.players.find(p=>p.id===seat);return{turn:s.turn,resources:p.resources,income:p.income,technology:p.techState,hand:p.hand.map(c=>({id:c.id,cardId:c.cardId})),reserved:p.reservedCards.map(c=>({id:c.id,cardId:c.cardId})),data:p.dataState,probes:s.pieces.rockets.filter(p=>p.playerId===seat),rng:s.meta.rngState,sectorWins:s.data.sectorSettlements.winsByPlayerId[seat],finalScoring:s.finalScoring,aliens:s.aliens};}
